/**
 * @module MommaPageLayout
 *
 * Layout decorativo de página com identidade visual Momma.
 * Inclui faixa de toldo na parte superior, folhas animadas no fundo
 * e brilhos ambientes sutis.
 */

import React from 'react';
import { Leaf, Sun, Moon, Sparkles } from 'lucide-react'; // Added Sparkles here just in case, though unrelated to layout background directly
import { cn } from '@/shared/lib/utils';
import { useTheme } from 'next-themes';
import { Button } from '@/shared/ui/button';

interface MommaPageLayoutProps {
  children: React.ReactNode;
  className?: string;
  showAwning?: boolean;
  pageTitle?: string; // Optional: for pages that want a consistent title header
}

/**
 * Layout de página com elementos decorativos da marca Momma.
 * Renderiza faixa de toldo, folhas animadas e brilhos ambientes como fundo.
 *
 * @param children - Conteúdo principal da página.
 * @param className - Classes CSS adicionais para o container de conteúdo.
 * @param showAwning - Se exibe a faixa de toldo no topo (padrão: `true`).
 * @param pageTitle - Título opcional da página (reservado para uso futuro).
 */
export function MommaPageLayout({
  children,
  className,
  showAwning = true,
  pageTitle,
}: MommaPageLayoutProps) {
  const { theme, setTheme } = useTheme();

  return (
    <div className="flex flex-col min-h-[100dvh] bg-white dark:bg-[#0A0A0A] overflow-x-hidden relative font-sans transition-colors duration-300">
      {/* Store Awning Stripe Effect (Top Border) */}
      {showAwning && (
        <div className="absolute top-0 left-0 right-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80 z-50 pointer-events-none" />
      )}

      {/* Animated Plant Background Elements */}
      <div className="fixed inset-0 pointer-events-none overflow-hidden z-0">
        <div
          className="absolute top-[-5%] right-[-10%] w-[300px] h-[300px] opacity-[0.03] dark:opacity-[0.05] animate-pulse"
          style={{ animationDuration: '10s' }}
        >
          <Leaf className="w-full h-full text-[#57715B] rotate-12" />
        </div>
        <div
          className="absolute bottom-[-10%] left-[-15%] w-[400px] h-[400px] opacity-[0.03] dark:opacity-[0.05] animate-pulse delay-1000"
          style={{ animationDuration: '12s' }}
        >
          <Leaf className="w-full h-full text-[#57715B] -rotate-45" />
        </div>

        {/* Soft Ambient Glows */}
        <div className="absolute top-[20%] left-[10%] w-[200px] h-[200px] bg-[#57715B]/5 rounded-full blur-[80px]" />
        <div className="absolute bottom-[30%] right-[10%] w-[250px] h-[250px] bg-[#C5A065]/5 rounded-full blur-[80px]" />
      </div>

      {/* Main Content */}
      <div className={cn('relative z-10 flex-1 flex flex-col', className)}>
        {children}
      </div>

      {/* Floating Theme Toggle (Optional - usually in header, but keeping layout distinct) */}
      {/* This layout focuses on background. Headers are usually page specific or DashboardLayout specific. 
                 Using this effectively means wrapping current page content. */}
    </div>
  );
}

