/**
 * Tipos de domínio da feature Ouvidoria.
 *
 * DenunciaOuvidoria omite senha_hash para nunca expor o hash ao client.
 * MensagemThread restringe autor a union explícita (o banco pode guardar
 * qualquer string, mas só produzimos 'denunciante' | 'ouvidoria').
 */

// ---------------------------------------------------------------------------
// Enums de domínio
// ---------------------------------------------------------------------------

export type CategoriaOuvidoria =
  | 'assedio_moral'
  | 'assedio_sexual'
  | 'fraude_financeiro'
  | 'discriminacao'
  | 'seguranca_trabalho'
  | 'conduta_etica'
  | 'sugestao'
  | 'outro';

export type StatusOuvidoria =
  | 'recebida'
  | 'em_analise'
  | 'resolvida'
  | 'arquivada';

// ---------------------------------------------------------------------------
// Entidade — painel das donas
// ---------------------------------------------------------------------------

/**
 * Linha da tabela ouvidoria_denuncias com senha_hash omitida.
 * Derivado manualmente do Row type do banco para garantir ausência do campo
 * sensível em tempo de compilação.
 */
export interface DenunciaOuvidoria {
  id: string;
  protocolo: string;
  categoria: CategoriaOuvidoria;
  loja_id: number | null;
  mensagem: string;
  status: StatusOuvidoria;
  created_at: string;
  updated_at: string;
  ultima_resposta_em: string | null;
}

// ---------------------------------------------------------------------------
// Thread de mensagens
// ---------------------------------------------------------------------------

export interface MensagemThread {
  autor: 'denunciante' | 'ouvidoria';
  mensagem: string;
  created_at: string;
}

// ---------------------------------------------------------------------------
// Resultado da consulta por protocolo (canal anônimo)
// ---------------------------------------------------------------------------

export interface ConsultaProtocoloDenuncia {
  protocolo: string;
  categoria: CategoriaOuvidoria;
  loja_id: number | null;
  mensagem: string;
  status: StatusOuvidoria;
  created_at: string;
  updated_at: string;
  ultima_resposta_em: string | null;
}

export type ConsultaProtocoloResult =
  | { ok: true; denuncia: ConsultaProtocoloDenuncia; mensagens: MensagemThread[] }
  | { ok: false };

// ---------------------------------------------------------------------------
// Inputs de formulário / mutation
// ---------------------------------------------------------------------------

export interface EnviarDenunciaInput {
  categoria: CategoriaOuvidoria;
  loja_id: number | null;
  mensagem: string;
  senha: string;
}

export interface ConsultarProtocoloInput {
  protocolo: string;
  senha: string;
}

export interface ResponderProtocoloInput {
  protocolo: string;
  senha: string;
  mensagem: string;
}

export interface ResponderOuvidoriaInput {
  denuncia_id: string;
  mensagem: string;
}

export interface AtualizarStatusInput {
  denuncia_id: string;
  status: StatusOuvidoria;
}

// ---------------------------------------------------------------------------
// Filtros do painel
// ---------------------------------------------------------------------------

export interface OuvidoriaFiltros {
  status?: StatusOuvidoria;
  categoria?: CategoriaOuvidoria;
  lojaId?: number;
}

/**
 * Labels e helpers para categorias e status da ouvidoria.
 * Dados estáticos — sem efeitos colaterais, safe para importar em qualquer contexto.
 */

import type { CategoriaOuvidoria, StatusOuvidoria } from '../types';

// ---------------------------------------------------------------------------
// Categorias
// ---------------------------------------------------------------------------

export const CATEGORIAS_OUVIDORIA: { value: CategoriaOuvidoria; label: string }[] = [
  { value: 'assedio_moral', label: 'Assédio moral' },
  { value: 'assedio_sexual', label: 'Assédio sexual' },
  { value: 'fraude_financeiro', label: 'Fraude / Financeiro' },
  { value: 'discriminacao', label: 'Discriminação' },
  { value: 'seguranca_trabalho', label: 'Segurança do trabalho' },
  { value: 'conduta_etica', label: 'Conduta ética' },
  { value: 'sugestao', label: 'Sugestão' },
  { value: 'outro', label: 'Outro' },
];

// ---------------------------------------------------------------------------
// Status
// ---------------------------------------------------------------------------

export const STATUS_OUVIDORIA: { value: StatusOuvidoria; label: string }[] = [
  { value: 'recebida', label: 'Recebida' },
  { value: 'em_analise', label: 'Em análise' },
  { value: 'resolvida', label: 'Resolvida' },
  { value: 'arquivada', label: 'Arquivada' },
];

// ---------------------------------------------------------------------------
// Helpers de exibição
// ---------------------------------------------------------------------------

export function labelCategoria(value: CategoriaOuvidoria): string {
  return CATEGORIAS_OUVIDORIA.find((c) => c.value === value)?.label ?? value;
}

export function labelStatus(value: StatusOuvidoria): string {
  return STATUS_OUVIDORIA.find((s) => s.value === value)?.label ?? value;
}

