3	 *
4	 * RLS garante que apenas usuários na allowlist (ouvidoria_acesso) recebem dados.
5	 * Colunas explícitas — senha_hash é deliberadamente excluída da seleção.
6	 *
7	 * Filtros são opcionais; queryKey os inclui para que o React Query mantenha
8	 * caches independentes por combinação de filtros.
9	 */
10	
11	import { useQuery } from '@tanstack/react-query';
12	import { supabase } from '@/integrations/supabase/client';
13	import type { DenunciaOuvidoria, OuvidoriaFiltros } from '../types';
