15	const COLUNAS =
16	  'id, protocolo, categoria, loja_id, mensagem, status, created_at, updated_at, ultima_resposta_em';
17	
18	export function useOuvidoriaList(filtros: OuvidoriaFiltros = {}) {
19	  return useQuery<DenunciaOuvidoria[]>({
20	    queryKey: ['ouvidoria', 'list', filtros],
21	    queryFn: async () => {
22	      let query = supabase
23	        .from('ouvidoria_denuncias' as any) // tabela tipada via schema gerado
24	        .select(COLUNAS)
25	        .order('created_at', { ascending: false });
26	
27	      if (filtros.status) {
28	        query = (query as any).eq('status', filtros.status);
29	      }
30	      if (filtros.categoria) {
31	        query = (query as any).eq('categoria', filtros.categoria);
32	      }
33	      if (filtros.lojaId !== undefined) {
34	        query = (query as any).eq('loja_id', filtros.lojaId);
35	      }
36	
37	      const { data, error } = await query;
38	      if (error) throw new Error(error.message);
39	      return (data ?? []) as unknown as DenunciaOuvidoria[];
