  const { isAdmin } = usePermissions();
  const isSystemAdmin = isAdmin();
  const { cargos } = useCargos();
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<EmployeeStatus | 'todos'>('todos');
  const [cargoFilter, setCargoFilter] = useState<string>('todos');
  const [aniversariantes, setAniversariantes] = useState(false);
  const [editandoPosto, setEditandoPosto] = useState<EmployeeListItem | null>(null);

  const filters = useMemo<EmployeeFilters>(
    () => ({
      loja_id: selectedStore?.id ?? null,
      search: search.trim() || undefined,
      status: statusFilter === 'todos' ? null : statusFilter,
      cargo_id: cargoFilter === 'todos' ? null : cargoFilter,
      aniversariantes_mes: aniversariantes ? new Date().getMonth() + 1 : null,
    }),
    [selectedStore?.id, search, statusFilter, cargoFilter, aniversariantes],
